-- Third-party risk (TPRM) v2, Phase 2 slice 4: evidence and findings on an
-- assessment. See docs/tprm-v2-spec.md sections 4 and 6.
--
-- tp_evidence: one row per file a consultant uploads to an assessment. The
-- file itself is stored by the app's existing upload pipeline (multer disk
-- storage under uploads/firm_<id>/, validated by lib/upload-security.js), the
-- same place as ISO evidence; stored_path is the generated file name inside
-- that directory and is never shown to anyone. sha256 is computed from the
-- stored bytes. A file is uploaded once per assessment (unique sha256).
-- source is consultant in Phase 2; vendor is reserved for Phase 3 uploads.
-- released_to_client is the consultant's file-by-file release to the client
-- (the portal shows released files from slice 6). Release is one-way, and a
-- released file can never be deleted: the guard trigger below enforces both,
-- and fixes the file columns once written. Like tp_events, the guard lets a
-- delete through once the workspace row itself is gone (a direct workspace
-- delete), and lib/workspace-deletion.js suspends it when it purges a client.
--
-- tp_findings: what the consultant found, per assessment: an ISO 27001
-- control reference (free text such as "A.5.20"), severity, title,
-- description, status open/closed. source is consultant in Phase 2;
-- ai_accepted is reserved for Phase 4 (an accepted AI suggestion).
--
-- tp_finding_evidence: the files a finding cites. Both composite foreign keys
-- carry assessment_id, so a finding can only cite files of its own
-- assessment (and so of its own client). Removing a finding removes its
-- links; a file that a finding cites cannot be deleted until the link is
-- removed (no ON DELETE action on the evidence key).
--
-- No row here is ever moved to another assessment. Assessments are never
-- deleted (cancelled instead); deleting a whole workspace removes these rows
-- with it. uploaded_by / released_by / created_by / updated_by carry no user
-- foreign key, as for the audit log (migration 086): the record outlives the
-- user.

CREATE TABLE IF NOT EXISTS tp_evidence (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  workspace_id bigint NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  assessment_id bigint NOT NULL,
  original_name text NOT NULL CHECK (length(btrim(original_name)) BETWEEN 1 AND 255),
  stored_path text NOT NULL CHECK (stored_path ~ '^[A-Za-z0-9][A-Za-z0-9_.-]*$' AND length(stored_path) <= 400),
  size_bytes bigint NOT NULL CHECK (size_bytes >= 0),
  mime_type text CHECK (length(mime_type) <= 200),
  sha256 text NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
  description text CHECK (length(description) <= 1000),
  source text NOT NULL DEFAULT 'consultant' CHECK (source IN ('consultant', 'vendor')),
  uploaded_by bigint,
  uploaded_at timestamptz NOT NULL DEFAULT now(),
  released_to_client boolean NOT NULL DEFAULT false,
  released_by bigint,
  released_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  row_version integer NOT NULL DEFAULT 1 CHECK (row_version >= 1),
  CONSTRAINT tp_evidence_workspace_id_id_key UNIQUE (workspace_id, id),
  CONSTRAINT tp_evidence_assessment_id_key UNIQUE (workspace_id, assessment_id, id),
  CONSTRAINT tp_evidence_assessment_fk FOREIGN KEY (workspace_id, assessment_id)
    REFERENCES tp_assessments (workspace_id, id),
  CONSTRAINT tp_evidence_release CHECK (
    (released_to_client AND released_by IS NOT NULL AND released_at IS NOT NULL)
    OR (NOT released_to_client AND released_by IS NULL AND released_at IS NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS tp_evidence_one_copy ON tp_evidence (workspace_id, assessment_id, sha256);
CREATE UNIQUE INDEX IF NOT EXISTS tp_evidence_stored_path_key ON tp_evidence (stored_path);
CREATE INDEX IF NOT EXISTS idx_tp_evidence_released ON tp_evidence (workspace_id, assessment_id) WHERE released_to_client;

CREATE OR REPLACE FUNCTION tp_evidence_guard_fn() RETURNS trigger
LANGUAGE plpgsql
AS $fn$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF NOT EXISTS (SELECT 1 FROM workspaces WHERE id = OLD.workspace_id) THEN
      RETURN OLD;
    END IF;
    IF OLD.released_to_client THEN
      RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
        MESSAGE = 'tp_evidence: a file released to the client cannot be deleted';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
     OR NEW.assessment_id IS DISTINCT FROM OLD.assessment_id OR NEW.original_name IS DISTINCT FROM OLD.original_name
     OR NEW.stored_path IS DISTINCT FROM OLD.stored_path OR NEW.size_bytes IS DISTINCT FROM OLD.size_bytes
     OR NEW.mime_type IS DISTINCT FROM OLD.mime_type OR NEW.sha256 IS DISTINCT FROM OLD.sha256
     OR NEW.source IS DISTINCT FROM OLD.source OR NEW.uploaded_by IS DISTINCT FROM OLD.uploaded_by
     OR NEW.uploaded_at IS DISTINCT FROM OLD.uploaded_at THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'tp_evidence: the file and who uploaded it cannot be changed';
  END IF;
  IF OLD.released_to_client AND (NOT NEW.released_to_client
     OR NEW.released_by IS DISTINCT FROM OLD.released_by OR NEW.released_at IS DISTINCT FROM OLD.released_at) THEN
    RAISE EXCEPTION USING ERRCODE = 'integrity_constraint_violation',
      MESSAGE = 'tp_evidence: a release to the client cannot be withdrawn or changed';
  END IF;
  RETURN NEW;
END;
$fn$;
DROP TRIGGER IF EXISTS tp_evidence_guard ON tp_evidence;
CREATE TRIGGER tp_evidence_guard BEFORE UPDATE OR DELETE ON tp_evidence
  FOR EACH ROW EXECUTE FUNCTION tp_evidence_guard_fn();

CREATE TABLE IF NOT EXISTS tp_findings (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  workspace_id bigint NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  assessment_id bigint NOT NULL,
  control_ref text CHECK (length(control_ref) <= 40),
  severity text NOT NULL CHECK (severity IN ('low', 'medium', 'high', 'critical')),
  title text NOT NULL CHECK (length(btrim(title)) BETWEEN 1 AND 200),
  description text CHECK (length(description) <= 4000),
  source text NOT NULL DEFAULT 'consultant' CHECK (source IN ('consultant', 'ai_accepted')),
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed')),
  created_by bigint,
  updated_by bigint,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  row_version integer NOT NULL DEFAULT 1 CHECK (row_version >= 1),
  CONSTRAINT tp_findings_workspace_id_id_key UNIQUE (workspace_id, id),
  CONSTRAINT tp_findings_assessment_id_key UNIQUE (workspace_id, assessment_id, id),
  CONSTRAINT tp_findings_assessment_fk FOREIGN KEY (workspace_id, assessment_id)
    REFERENCES tp_assessments (workspace_id, id)
);
CREATE INDEX IF NOT EXISTS idx_tp_findings_assessment ON tp_findings (workspace_id, assessment_id, id);

CREATE TABLE IF NOT EXISTS tp_finding_evidence (
  workspace_id bigint NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  assessment_id bigint NOT NULL,
  finding_id bigint NOT NULL,
  evidence_id bigint NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, finding_id, evidence_id),
  CONSTRAINT tp_finding_evidence_finding_fk FOREIGN KEY (workspace_id, assessment_id, finding_id)
    REFERENCES tp_findings (workspace_id, assessment_id, id) ON DELETE CASCADE,
  CONSTRAINT tp_finding_evidence_evidence_fk FOREIGN KEY (workspace_id, assessment_id, evidence_id)
    REFERENCES tp_evidence (workspace_id, assessment_id, id)
);
CREATE INDEX IF NOT EXISTS idx_tp_finding_evidence_evidence ON tp_finding_evidence (workspace_id, evidence_id);
